import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = rb();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = rb();
        StringBuilder sb = new StringBuilder();
        while (c != -1 && c != ' ' && c != '\n' && c != '\r' && c != '\t') {
            sb.append((char) c);
            c = rb();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        String state = next();
        // unlock[r]: largest value that becomes available in round r (distance to the nearest 1 on the left).
        long[] unlock = new long[n];
        int distance = n;
        for (int i = 0; i < n; i++) {
            distance = state.charAt(i) == '1' ? 0 : distance + 1;
            if (distance < n) unlock[distance] = Math.max(unlock[distance], a[i]);
        }
        if (unlock[0] == 0) {
            System.out.println(-1);
            return;
        }
        StringBuilder sb = new StringBuilder();
        long current = 0;
        for (int step = 0; step < m; step++) {
            if (step < n) current = Math.max(current, unlock[step]);
            sb.append(current).append(step + 1 < m ? ' ' : '\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := reader.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = reader.ReadByte()
	}
	var tok []byte
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		tok = append(tok, c)
		c, err = reader.ReadByte()
	}
	return string(tok)
}

func main() {
	n, m := readInt(), readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	state := readToken()
	// unlock[r]: largest value that becomes available in round r (distance to the nearest 1 on the left).
	unlock := make([]int, n)
	distance := n
	for i := 0; i < n; i++ {
		if state[i] == '1' {
			distance = 0
		} else {
			distance++
		}
		if distance < n {
			unlock[distance] = max(unlock[distance], a[i])
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	if unlock[0] == 0 {
		w.WriteString("-1\n")
		return
	}
	current := 0
	for step := 0; step < m; step++ {
		if step < n {
			current = max(current, unlock[step])
		}
		w.WriteString(strconv.Itoa(current))
		if step+1 < m {
			w.WriteByte(' ')
		} else {
			w.WriteByte('\n')
		}
	}
}
